// application.yml: bọc bằng ErrorHandlingDeserializer để record hỏng tới được error handler
// spring.kafka.consumer.value-deserializer: org.springframework.kafka.support.serializer.ErrorHandlingDeserializer
// spring.kafka.consumer.properties.spring.deserializer.value.delegate.class: com.shop.loyalty.OrderPlacedDeserializer

@Bean
DefaultErrorHandler errorHandler(KafkaTemplate<String, byte[]> bytesTemplate) {
    // template dùng ByteArraySerializer: record lỗi deserialize được gửi đi dưới dạng byte[] gốc
    // lỗi deserialize không retry, chuyển thẳng sang order-events-dlt (tên mặc định từ Spring Kafka 3.3;
    // DLT cần ít nhất bằng số partition của topic gốc)
    return new DefaultErrorHandler(new DeadLetterPublishingRecoverer(bytesTemplate), new FixedBackOff(1000, 3));
}
